"""This module provides the implementation to get the uplane_trace trace pcap file with help of
the command "get_log_file"
"""
import logging
import os

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CloudGnbUplaneTraceLogFileProvider:
    """Class to get the trace file for the uplane_trace trace. Currently the pcap files are returned
    """

    def get_uplane_trace_log_file(self, log_directory, collector_config):
        """Get the uplane_trace log path on vran testlines.
        """
        # find the uplane_trace trace path
        vdu_members = [member for member in collector_config['members'] if 'vdu' in member.lower()]

        # it should only be one vdu_member, else we don't have a uplane_trace trace
        if len(vdu_members) != 1:
            logger.warning(f"There should at least and only be one vdu collector for uplane_trace trace! {vdu_members}")
            return []

        decorating_collector = self._collector_configuration_data.get_configuration_by_collector_name(
            vdu_members[0])
        vdu_l2stream3_collector = self._collector_configuration_data.get_configuration_by_collector_name(
            decorating_collector['collector'])
        tcpdump_collector = self._collector_configuration_data.get_configuration_by_collector_name(
            vdu_l2stream3_collector['collector'])

        full_collector_path = os.path.join(
            log_directory,
            decorating_collector['name'],
            tcpdump_collector['name'])

        if not os.path.exists(full_collector_path):
            logger.error(f"The path {full_collector_path} doesn't exist")

        return [
            os.path.join(full_collector_path, pcap)
            for pcap in os.listdir(full_collector_path)
            if pcap.lower().endswith(pcap)]
